# -*- coding: utf-8 -*-
from odoo import models, fields, api

class CrmTeam(models.Model):
    _name = 'crm.team'
    _description = 'CRM TEAM'
    _order = 'id desc'

    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    name = fields.Char(string="Sales Team", required=True)
    sequence = fields.Integer(string="Sequence")
    active = fields.Boolean(string="Active", help="If the active field is set to false, it will allow you to hide the Sales Team without removing it.")
    company_id = fields.Many2one(comodel_name="res.company", string="Company")
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", readonly=True)
    user_id = fields.Many2one(comodel_name="res.users", string="Team Leader")
    is_membership_multi = fields.Boolean(string="Multiple Memberships Allowed", readonly=True, help="If True, users may belong to several sales teams. Otherwise membership is limited to a single sales team.")
    member_ids = fields.Many2many(comodel_name="res.users", string="Salespersons", help="Users assigned to this team.")
    member_company_ids = fields.Many2many(comodel_name="res.company", string="Member Company", readonly=True, help="UX: Limit to team company or all if no company")
    member_warning = fields.Text(string="Membership Issue Warning", readonly=True)
    crm_team_member_ids = fields.One2many(comodel_name="crm.team.member", inverse_name='parent_id', string="Sales Team Members", help="Add members to automatically assign their documents to this sales team.")
    crm_team_member_all_ids = fields.One2many(comodel_name="crm.team.member", inverse_name='parent_id', string="Sales Team Members (incl. inactive)")
    color = fields.Integer(string="Color Index", help="The color of the channel")
    favorite_user_ids = fields.Many2many(comodel_name="res.users", string="Favorite Members")
    is_favorite = fields.Boolean(string="Show on dashboard", help="Favorite teams to display them in the dashboard and access them easily.")
    dashboard_button_name = fields.Char(string="Dashboard Button", readonly=True)
    dashboard_graph_data = fields.Text(string="Dashboard Graph Data", readonly=True)
    crm_department_id = fields.Many2one(comodel_name="crm.department", string="Sales Department")
    department_manager_id = fields.Many2one(comodel_name="res.users", string="Sales Department Manager", readonly=True)
    alias_id = fields.Many2one(comodel_name="mail.alias", string="Alias", required=True, help="The email address associated with this channel. New emails received will automatically create new leads assigned to the channel.")
    use_leads = fields.Boolean(string="Leads", help="Check this box to filter and qualify incoming requests as leads before converting them into opportunities and assigning them to a salesperson.")
    use_opportunities = fields.Boolean(string="Pipeline", help="Check this box to manage a presales process with opportunities.")
    assignment_enabled = fields.Boolean(string="Lead Assign", readonly=True)
    assignment_auto_enabled = fields.Boolean(string="Auto Assignment", readonly=True)
    assignment_optout = fields.Boolean(string="Skip auto assignment")
    assignment_max = fields.Integer(string="Lead Average Capacity", readonly=True, help="Monthly average leads capacity for all salesmen belonging to the team")
    assignment_domain = fields.Char(string="Assignment Domain", help="Additional filter domain when fetching unassigned leads to allocate to the team.")
    lead_unassigned_count = fields.Integer(string="# Unassigned Leads", readonly=True)
    lead_all_assigned_month_count = fields.Integer(string="# Leads/Opps assigned this month", readonly=True, help="Number of leads and opportunities assigned this last month.")
    opportunities_count = fields.Integer(string="# Opportunities", readonly=True)
    opportunities_amount = fields.Monetary(string="Opportunities Revenues", readonly=True)
    opportunities_overdue_count = fields.Integer(string="# Overdue Opportunities", readonly=True)
    opportunities_overdue_amount = fields.Monetary(string="Overdue Opportunities Revenues", readonly=True)
    alias_user_id = fields.Many2one(comodel_name="res.users", string="Owner", help="The owner of records created upon receiving emails on this alias. If this field is not set the system will attempt to find the right owner based on the sender (From) address, or will use the Administrator account if no system user is found for that address.")
    lead_properties_definition = fields.Char(string="Lead Properties")
    alias_name = fields.Char(string="Alias Name", help="The name of the email alias, e.g. 'jobs' if you want to catch emails for <jobs@example.odoo.com>")
    alias_model_id = fields.Many2one(comodel_name="ir.model", string="Aliased Model", required=True, help="The model (Odoo Document Kind) to which this alias corresponds. Any incoming email that does not reply to an existing record will cause the creation of a new record of this model (e.g. a Project Task)")
    alias_defaults = fields.Text(string="Default Values", required=True, help="A Python dictionary that will be evaluated to provide default values when creating new records for this alias.")
    alias_force_thread_id = fields.Integer(string="Record Thread ID", help="Optional ID of a thread (record) to which all incoming messages will be attached, even if they did not reply to it. If set, this will disable the creation of new records completely.")
    alias_domain = fields.Char(string="Alias domain", readonly=True)
    alias_parent_model_id = fields.Many2one(comodel_name="ir.model", string="Parent Model", help="Parent model holding the alias. The model holding the alias reference is not necessarily the model given by alias_model_id (example: project (parent_model) and task (model))")
    alias_parent_thread_id = fields.Integer(string="Parent Record Thread ID", help="ID of the parent record holding the alias (example: project holding the task creation alias)")
    alias_contact = fields.Selection(selection=[["everyone","Everyone"],["partners","Authenticated Partners"],["followers","Followers only"],["employees","Authenticated Employees"]], string="Alias Contact Security", required=True, help="Policy to post a message on the document using the mailgateway.\n- everyone: everyone can post\n- partners: only authenticated partners\n- followers: only followers of the related document or members of following channels\n")
    alias_bounced_content = fields.Html(string="Custom Bounced Message", help="If set, this content will automatically be sent out to unauthorized users instead of the default message.")
